const CACHE='auralis-frontier-v7-world-3d';
const FILES=['./','./world-3d.js','./models-3d.js','./render-world.js','./vendor/three.module.js','./vendor/three.core.js','./vendor/THREE-LICENSE.txt','./assets/art/civic-buildings-v6.png','./civilization.js','./civilization-data.js','./civilization-ui.js','./realism-assets.js','./realism-frames.js','./landscape-render.js','./assets/art/settlements-v5.png','./assets/art/nature-v5.png','./assets/art/people-v5.png','./assets/art/transport-v5.png','./assets/art/terrain-v5.png','./classic.html','./sectors.js','./horizons.js','./horizons-render.js','./horizons-ui.js','./horizons-art.js','./horizons.css','./world-storage.js','./index.html','./styles.css','./app.js','./engine.js','./terrain.js','./renderer.js','./world.js','./art.js','./assets/art/shipyard-v3.png','./frontier.js','./frontier-ui.js','./assets/art/military-buildings-v3.png','./assets/art/military-troops-v3.png','./assets/art/historical-troops-v3.png','./assets/art/buildings.png','./assets/art/troops.png','./manifest.webmanifest','./icon.svg','./icon-192.png','./icon-512.png'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(FILES.map(f=>new Request(f,{cache:'reload'})))));self.skipWaiting();});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('auralis-frontier-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin||!FILES.some(f=>new URL(f,self.registration.scope).pathname===url.pathname))return;event.respondWith(fetch(event.request,{cache:'no-cache'}).then(response=>{if(response.ok){const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy));}return response;}).catch(()=>caches.match(event.request).then(cached=>cached||new Response('Sin conexión. Abre el juego en línea una vez para descargarlo.',{status:503,headers:{'Content-Type':'text/plain; charset=utf-8'}}))));});
